-- Image URLs are relative to the site root, so they work on any host.
INSERT INTO manga (title, author, genre, type, rating, image_url, description) VALUES
('Naruto', 'Masashi Kishimoto', 'Боевик', 'MANGA', 4.7, '/images/naruto_cover_page.jpg',
 'Наруто Узумаки — шумный сирота из Деревни Скрытого Листа, в котором запечатан демон-лис. Он мечтает стать Хокаге, чтобы деревня наконец его признала.'),
('Omniscient Reader''s Viewpoint', 'Sing Shong, Sleepy-C', 'Фэнтези', 'MANHWA', 4.4, '/images/omniscient_readers_viewpoint_cover_page.jpg',
 'Ким Докча десять лет читал никому не нужный веб-роман. Когда его сюжет становится реальностью, единственный читатель, знающий финал, получает шанс выжить.'),
('Windbreaker', 'Jo Yongseok', 'Спорт', 'MANHWA', 4.8, '/images/windbreaker_cover_page.jpg',
 'Отличник Джей Чжо живёт по расписанию: учёба, дом, снова учёба. Но по ночам он гоняет на велосипеде — и однажды попадает в мир уличных райдеров, где решают скорость и команда.'),
('The Beginning After the End', 'TurtleMe, Fuyuki23', 'Фэнтези', 'MANHWA', 4.9, '/images/the_beginning_after_the_end.jpg',
 'Король Грей обладал всей властью мира, но не нашёл в ней смысла. Переродившись в мире магии и монстров, он получает второй шанс прожить жизнь иначе.'),
('White Blood', 'Автор уточняется', 'Фэнтези', 'MANHWA', 4.2, '/images/white_blood_cover_page.jpg',
 'Описание скоро появится.'),
('Сволочь', 'Carnby Kim, Youngchan Hwang', 'Триллер', 'MANHWA', 3.9, '/images/scum_cover_page.jpg',
 'Тихий школьник Сон Джин скрывает страшную тайну: его отец — серийный убийца, а сам он вынужден помогать ему. Мрачный психологический триллер.'),
('Милый дом', 'Carnby Kim, Youngchan Hwang', 'Ужасы', 'MANHWA', 4.0, '/images/sweet_home_cover_page.jpg',
 'Замкнутый подросток Хён Су переезжает в новый дом — и люди вокруг начинают превращаться в чудовищ, воплощающих их тайные желания.'),
('Steel Ball Run', 'Hirohiko Araki', 'Приключения', 'MANGA', 5.0, '/images/steel_ball_run_cover_page.jpg',
 '1890 год. Тысячи всадников стартуют в гонке через всю Америку. Бывший жокей Джонни Джостар и загадочный Джайро Цеппели ищут в ней не только приз.'),
('One-Punch Man', 'ONE, Yusuke Murata', 'Комедия', 'MANGA', 4.6, '/images/one_punch_man_cover_page.jpg',
 'Сайтама побеждает любого врага одним ударом — и именно поэтому ему смертельно скучно. Пародия на супергероику с одной из лучших рисовок в жанре.'),
('Solo Leveling', 'Chugong, DUBU', 'Фэнтези', 'MANHWA', 3.7, '/images/solo_leveling_cover_page.jpg',
 'Сон Джину — слабейший охотник E-ранга. После рейда в двойном подземелье он получает Систему, которая позволяет ему расти без предела.'),
('Attack on Titan', 'Hajime Isayama', 'Драма', 'MANGA', 4.8, '/images/attack_on_titan_cover_page.jpg',
 'Человечество живёт за огромными стенами, спасаясь от титанов. Когда стена падает, Эрен Йегер клянётся истребить их всех — и узнаёт, что правда о мире страшнее.'),
('My Hero Academia', 'Kohei Horikoshi', 'Боевик', 'MANGA', 4.5, '/images/my_hero_academia_cover_page.jpg',
 'В мире, где почти у всех есть причуда, Изуку Мидория родился без неё. Встреча с величайшим героем меняет всё.'),
('Tokyo Ghoul', 'Sui Ishida', 'Ужасы', 'MANGA', 4.6, '/images/tokyo_ghoul_cover_page.jpg',
 'Студент Канеки Кен становится наполовину гулем и вынужден жить между двумя мирами, ни один из которых его не принимает.'),
('Death Note', 'Tsugumi Ohba, Takeshi Obata', 'Триллер', 'MANGA', 4.9, '/images/death_note_cover_page.jpg',
 'Лайт Ягами находит тетрадь, которая убивает любого, чьё имя в неё вписано. Начинается интеллектуальная дуэль гения и детектива L.'),
('Demon Slayer', 'Koyoharu Gotouge', 'Боевик', 'MANGA', 4.7, '/images/demon_slayer_cover_page.jpg',
 'Семью Танджиро Камадо убил демон, а сестра Нэзуко сама стала демоном. Чтобы вернуть ей человечность, Танджиро вступает в Корпус истребителей демонов.'),
('Bleach', 'Tite Kubo', 'Боевик', 'MANGA', 4.3, '/images/bleach_cover_page.jpg',
 'Ичиго Куросаки видит призраков. Получив силу синигами, он начинает защищать живых от пустых — и втягивается в войну загробного мира.'),
('Vagabond', 'Takehiko Inoue', 'Драма', 'MANGA', 4.8, '/images/vagabond_cover_page.jpg',
 'История Миямото Мусаси — от озлобленного юноши до величайшего мечника Японии. Медитативная манга о силе, одиночестве и пути.'),
('Black Clover', 'Yūki Tabata', 'Фэнтези', 'MANGA', 4.4, '/images/black_clover_cover_page.jpg',
 'В мире, где магия есть у всех, сирота Аста родился без неё. Вооружившись антимагическим мечом, он идёт к цели — стать Королём магов.'),
('Chainsaw Man', 'Tatsuki Fujimoto', 'Боевик', 'MANGA', 4.6, '/images/chainsaw_man_cover_page.jpg',
 'Денджи по уши в долгах и охотится на демонов вместе с псом-бензопилой Почитой. После предательства он сам становится человеком-бензопилой.'),
('Hunter x Hunter', 'Yoshihiro Togashi', 'Приключения', 'MANGA', 4.9, '/images/hunter_x_hunter_cover_page.jpg',
 'Гон Фрикс узнаёт, что его отец — легендарный охотник, и отправляется на экзамен охотников, чтобы найти его.');
